/* From Uiverse.io by vinodjangid07 - Tags: icon, button, pay */
.__UIV_SCOPE__ .Btn {
  width: 130px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: rgb(15, 15, 15);
  border: none;
  color: white;
  font-weight: 600;
  gap: 8px;
  cursor: pointer;
  box-shadow: 5px 5px 10px rgba(0, 0, 0, 0.103);
  position: relative;
  overflow: hidden;
  transition-duration: .3s;
}

.__UIV_SCOPE__ .svgIcon {
  width: 16px;
}

.__UIV_SCOPE__ .svgIcon path {
  fill: white;
}

.__UIV_SCOPE__ .Btn::before {
  width: 130px;
  height: 130px;
  position: absolute;
  content: "";
  background-color: white;
  border-radius: 50%;
  left: -100%;
  top: 0;
  transition-duration: .3s;
  mix-blend-mode: difference;
}

.__UIV_SCOPE__ .Btn:hover::before {
  transition-duration: .3s;
  transform: translate(100%,-50%);
  border-radius: 0;
}

.__UIV_SCOPE__ .Btn:active {
  transform: translate(5px,5px);
  transition-duration: .3s;
}
